import Vue from 'vue'
import Router from 'vue-router'
import HomePage from '@/views/HomePage'

Vue.use(Router)

export default new Router({
  routes: [
    {
      path: '/',
      name: 'HomePage',
      component: HomePage
    },
    {
      path: '/school-overview',
      name: 'SchoolOverview',
      component: () => import('../views/SchoolOverview.vue')
    },
    // 修改教学教研路由，指向TeachingAndResearch文件夹
    {
      path: '/teaching',
      name: 'TeachingPage',
      component: () => import('../TeachingAndResearch/TeachingPage.vue')
    },
    // 添加德育之窗路由
    {
      path: '/moral-education',
      name: 'MoralEducationPage',
      component: () => import('../views/MoralEducationPage.vue')
    },
    // 其他暂时注释掉没有对应文件的路由
    /*
    {
      path: '/news',
      name: 'NewsPage',
      component: () => import('../views/NewsPage.vue')
    },
    {
      path: '/culture',
      name: 'CulturePage',
      component: () => import('../views/CulturePage.vue')
    },
    */
    {
      path: '/admission',
      name: 'AdmissionPage',
      component: () => import('../views/AdmissionPage.vue')
    },
    {
      path: '/recruitment',
      name: 'RecruitmentPage',
      component: () => import('../views/RecruitmentPage.vue')
    },
    {
      path: '/contact',
      name: 'ContactPage',
      component: () => import('../views/ContactPage.vue')
    }
  ]
})
